def firstUniqChar(s):
    if (s.strip()==""):
        return 0
    # listofOutliers=[""]
    count=0
    for i in range(len(s)):
        count=0
        for k in s:
            # if i in listofOutliers:
            #     break
            if s[i]==k:
                count+=1
            if count>=2:
                # listofOutliers.append(i)
                break    
        if count==1:
            return i
    return -1    



print("leetcode: "+str(firstUniqChar("leetcode")))      
print("loveleetcode: "+str(firstUniqChar("loveleetcode")))     
print("aabb: "+str(firstUniqChar("aabb")))     
print("jabrish string: "+str(firstUniqChar("")))     



            